      : service.getReport(
          authenticated,
          reference.data,
          query.success ? query.data : { limit: 50 },
        );
    void result
      .then((body) => {
        if (download) {
          response.attachment(`batch-${reference.data}-report.json`);
          response.type('application/json');
        }
        response.json(body);
      })
      .catch((error: unknown) => {
        if (rejectReadError(response, error)) return;
        next(error);
      });
  };
}

