              f.fixture_id,
              f.source_ref,
              f.competition_id,
              f.season,
              f.start_date,
              v.name`,
          [fixtureSourceValues],
        ).then((result) => result.rows)
      : Promise.resolve<FixtureBySourceRefRow[]>([]),
    competitionId !== null && fixtureDates.length > 0
      ? executeQuery<FixtureByNaturalKeyRow>(
          client,
