function ReviewQueue() {
  const client = useAuthenticatedApiClient();
  const [loadingMore, setLoadingMore] = useState(false);
  const [loadMoreError, setLoadMoreError] = useState<string | null>(null);
  const [state, setState] = useState<
    LoadState<{ profile: CurrentUserProfile; batches: BatchStatus[]; cursor: string | null }>
  >({ kind: 'loading' });

  useEffect(() => {
    const controller = new AbortController();
    void Promise.all([
      getCurrentUserProfile(client, controller.signal),
      listBatches(client, undefined, 'awaiting_review'),
    ])
      .then(([profile, response]) =>
        setState({
          kind: 'ready',
          value: { profile, batches: response.data, cursor: response.pagination.nextCursor },
        }),
      )
      .catch(() => {
        if (!controller.signal.aborted)
          setState({ kind: 'error', message: 'The review queue could not be loaded.' });
      });
    return () => controller.abort();
  }, [client]);

  if (state.kind === 'loading') return <p role="status">Loading review queueâ€¦</p>;
  if (state.kind === 'error') return <p role="alert">{state.message}</p>;
  async function loadMore() {
    if (state.kind !== 'ready' || !state.value.cursor) return;
    setLoadingMore(true);
    setLoadMoreError(null);
    try {
      const response = await listBatches(client, state.value.cursor, 'awaiting_review');
      setState({
        kind: 'ready',
        value: {
          ...state.value,
          batches: [...state.value.batches, ...response.data],
          cursor: response.pagination.nextCursor,
        },
      });
    } catch {
      setLoadMoreError('More queued batches could not be loaded.');
    } finally {
      setLoadingMore(false);
    }
  }
  return (
    <ReviewerGate profile={state.value.profile}>
      <p className="review-scope-note">Showing all awaiting-review batches.</p>
      {state.value.batches.length === 0 ? (
        <p role="status">No batches are awaiting your review.</p>
      ) : (
        <ul className="batch-list review-queue">
          {state.value.batches.map((batch) => (
            <li key={batch.batchReference}>
              <div>
                <Link to={`/reviews/batches/${batch.batchReference}`}>
                  {batch.source.fileName ?? batch.batchReference}
                </Link>
                <span>
                  {batch.source.submitter.displayName ??
                    `Account ${batch.source.submitter.accountId}`}
                </span>
              </div>
              <span>
                {batch.progress.total} items Â· received{' '}
                {new Date(batch.receivedAt).toLocaleString()}
              </span>
            </li>
          ))}
        </ul>
      )}
      {state.value.cursor ? (
        <button
          className="button button--secondary"
          type="button"
          disabled={loadingMore}
          onClick={() => void loadMore()}
        >
          {loadingMore ? 'Loadingâ€¦' : 'Load more batches'}
        </button>
      ) : null}
      {loadMoreError ? <p role="alert">{loadMoreError}</p> : null}
    </ReviewerGate>
  );
}

function ConfirmationDialog({
  decision,
  reason,
  saving,
  onCancel,
  onConfirm,
}: {
  decision: BatchReviewRequest['decision'];
  reason: string;
  saving: boolean;
  onCancel(): void;
  onConfirm(): void;
}) {
  const cancelRef = useRef<HTMLButtonElement>(null);
  const confirmRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    cancelRef.current?.focus();
    const close = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !saving) onCancel();
      if (event.key === 'Tab') {
        if (event.shiftKey && document.activeElement === cancelRef.current) {
          event.preventDefault();
          confirmRef.current?.focus();
        } else if (!event.shiftKey && document.activeElement === confirmRef.current) {
          event.preventDefault();
          cancelRef.current?.focus();
        }
      }
    };
    document.addEventListener('keydown', close);
    return () => document.removeEventListener('keydown', close);
  }, [onCancel, saving]);
  const label =
    decision === 'approved'
      ? 'Approve and publish'
      : decision === 'rejected'
        ? 'Reject batch'
        : 'Return for correction';
  return (
    <div className="review-dialog-backdrop">
      <section
        className="review-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="review-confirm-title"
        aria-describedby="review-confirm-description"
      >
        <h2 id="review-confirm-title">Confirm {label.toLowerCase()}</h2>
        <p id="review-confirm-description">
          This records a reviewer decision and changes the batch lifecycle. Reason: {reason}
        </p>
        <div className="batch-review__actions">
          <button
            ref={cancelRef}
            className="button button--secondary"
            type="button"
            onClick={onCancel}
            disabled={saving}
          >
            Cancel
          </button>
          <button
            ref={confirmRef}
            className={decision === 'rejected' ? 'button button--danger' : 'button button--primary'}
            type="button"
            onClick={onConfirm}
            disabled={saving}
          >
            {saving ? 'Savingâ€¦' : `Confirm ${label.toLowerCase()}`}
          </button>
        </div>
      </section>
    </div>
  );
}

